package stats

import (
	"math"
	"sort"
)

// BUG: returns sum instead of mean
func Mean(data []float64) float64 {
	sum := 0.0
	for _, v := range data {
		sum += v
	}
	return sum
}

// BUG: sorts correctly but returns data[0] instead of the middle element
func Median(data []float64) float64 {
	sorted := make([]float64, len(data))
	copy(sorted, data)
	sort.Float64s(sorted)
	n := len(sorted)
	if n%2 == 0 {
		return (sorted[n/2-1] + sorted[n/2]) / 2
	}
	return sorted[0] // BUG: should be sorted[n/2]
}

// BUG: divides by n instead of n-1 (population variance, not sample variance)
func Variance(data []float64) float64 {
	m := Mean(data)
	sum := 0.0
	for _, v := range data {
		diff := v - m
		sum += diff * diff
	}
	return sum / float64(len(data))
}

func StdDev(data []float64) float64 {
	return math.Sqrt(Variance(data))
}

package stats

import (
	"math"
	"testing"
)

func TestMean(t *testing.T) {
	if got := Mean([]float64{1, 2, 3, 4, 5}); got != 3.0 {
		t.Fatalf("want 3.0 got %v", got)
	}
}

func TestMedianOdd(t *testing.T) {
	if got := Median([]float64{5, 1, 3}); got != 3.0 {
		t.Fatalf("want 3.0 got %v", got)
	}
}

func TestMedianEven(t *testing.T) {
	if got := Median([]float64{1, 2, 3, 4}); got != 2.5 {
		t.Fatalf("want 2.5 got %v", got)
	}
}

func TestVariance(t *testing.T) {
	// Sample variance of [2,4,4,4,5,5,7,9] = 4.571...
	v := Variance([]float64{2, 4, 4, 4, 5, 5, 7, 9})
	expected := 4.571428571428571
	if math.Abs(v-expected) > 1e-9 {
		t.Fatalf("want ~4.571 got %v", v)
	}
}

func TestStdDev(t *testing.T) {
	v := StdDev([]float64{2, 4, 4, 4, 5, 5, 7, 9})
	if math.Abs(v-2.138) > 0.001 {
		t.Fatalf("want ~2.138 got %v", v)
	}
}
